#include <iostream>
#include <cstring>
using std::cin;
using std::cout;
using std::endl;

int main()
{
    char szStr1[32];
    char szStr2[32];
    char szStr3[32];

    cout << "문자열 1: ";
    cin >> szStr1;
    cout << "문자열 2: ";
    cin >> szStr2;
    cout << "문자열 3: ";
    cin >> szStr3;

    int nLen1 = (int)strlen(szStr1);
    int nLen2 = (int)strlen(szStr2);
    int nLen3 = (int)strlen(szStr3);

    // 1. 가장 긴 문자열을 제외한 두 개를, 더 짧은 것이 앞에 오도록 합친다.
    char szCombined[64] = "";

    if (nLen1 >= nLen2 && nLen1 >= nLen3)
    {
        // szStr1이 가장 길다 -> szStr2, szStr3을 합친다
        if (nLen2 <= nLen3)
        {
            strcat_s(szCombined, szStr2);
            strcat_s(szCombined, szStr3);
        }
        else
        {
            strcat_s(szCombined, szStr3);
            strcat_s(szCombined, szStr2);
        }
    }
    else if (nLen2 >= nLen1 && nLen2 >= nLen3)
    {
        // szStr2가 가장 길다 -> szStr1, szStr3을 합친다
        if (nLen1 <= nLen3)
        {
            strcat_s(szCombined, szStr1);
            strcat_s(szCombined, szStr3);
        }
        else
        {
            strcat_s(szCombined, szStr3);
            strcat_s(szCombined, szStr1);
        }
    }
    else
    {
        // szStr3이 가장 길다 -> szStr1, szStr2를 합친다
        if (nLen1 <= nLen2)
        {
            strcat_s(szCombined, szStr1);
            strcat_s(szCombined, szStr2);
        }
        else
        {
            strcat_s(szCombined, szStr2);
            strcat_s(szCombined, szStr1);
        }
    }

    // 2. 사전순으로 가장 뒤에 오는 문자열을 찾는다.
    char szResult[128] = "";

    if (strcmp(szStr1, szStr2) > 0 && strcmp(szStr1, szStr3) > 0)
    {
        strcpy_s(szResult, szStr1);
    }
    else if (strcmp(szStr2, szStr1) > 0 && strcmp(szStr2, szStr3) > 0)
    {
        strcpy_s(szResult, szStr2);
    }
    else
    {
        strcpy_s(szResult, szStr3);
    }

    // 3. 가장 뒤에 오는 문자열 뒤에 합친 문자열을 붙인다.
    strcat_s(szResult, szCombined);
    cout << "Result: " << szResult << endl;

    return 0;
}
